from fastapi import APIRouter, Body, HTTPException
from sqlalchemy import Column, Integer, String, Float, Boolean
from sqlalchemy.orm import Session
from app.extensions import Base, SessionLocal

router = APIRouter()

class TorrentResult(Base):
    __tablename__ = "torrent_results"
    id = Column(Integer, primary_key=True)
    name = Column(String)
    size = Column(String)
    date = Column(String)

@router.post("")
def sort_torrent_results(results: list[dict[str, str]] = Body(..., embed=True), sort_by: str = Body(..., embed=True)) -> list[dict[str, str]]:
    # Validate sort_by parameter
    valid_sort_criteria = ["size", "date", "alphabetical"]
    if sort_by not in valid_sort_criteria:
        raise HTTPException(status_code=400, detail="Invalid sort_by criterion")

    # Handle empty results case
    if not results:
        return []

    # Sort based on the sort_by criterion
    if sort_by == "size":
        # For size sorting, we need to extract numeric values
        # Assuming size is in format like "1GB", "2MB", etc.
        def size_to_bytes(size_str):
            size_str = size_str.upper()
            if "GB" in size_str:
                return float(size_str.replace("GB", "")) * 1024 * 1024 * 1024
            elif "MB" in size_str:
                return float(size_str.replace("MB", "")) * 1024 * 1024
            elif "KB" in size_str:
                return float(size_str.replace("KB", "")) * 1024
            else:
                return float(size_str)

        return sorted(results, key=lambda x: size_to_bytes(x["size"]))

    elif sort_by == "date":
        # Sort by date (assuming ISO format)
        return sorted(results, key=lambda x: x["date"])

    elif sort_by == "alphabetical":
        # Sort alphabetically by name
        return sorted(results, key=lambda x: x["name"])

    # This should never happen due to validation above
    raise HTTPException(status_code=400, detail="Invalid sort_by criterion")

